/** Одно прошлое дело в списке возврата — см. storyPastCases. */
export interface StoryPastCase {
  week: StoryWeek;
  /** Порядковый номер недели (с единицы) — для подписи вида «Неделя 2». */
  weekNumber: number;
  /** Последний день той недели: оттуда полоса снова навигация по всем её дням. */
  lastDayId: string;
}

/**
 * Все недели строго до текущей, каждая — со своим вопросом расследования
 * и входом в свой итог.
 *
 * Раньше здесь была только предыдущая неделя (одна дверь на брифе понедельника),
 * и вернуться на две недели назад значило дважды дойти до понедельника и дважды
 * нажать дверь. Список прошлых дел открыт для возврата с любого экрана кампании
 * (см. StoryProgress), а не только с брифа понедельника, — вспомнить про находку
 * из третьей недели можно посреди пятой.
 *
 * Ведёт именно в последний день недели, а не в первый: оттуда полоса той недели
 * снова навигация, и любой её день — в одном клике.
 */
export function storyPastCases(campaign: StoryCampaign, missionId: string): StoryPastCase[] {
  const mission = campaign.missions.find((m) => m.id === missionId);
  if (!mission) return [];
  const wi = campaign.weeks.findIndex((w) => w.id === mission.week);
  if (wi <= 0) return [];
  return campaign.weeks
    .slice(0, wi)
    .map((week, i) => {
      const days = campaign.missions.filter((m) => m.week === week.id);
      return { week, weekNumber: i + 1, lastDayId: days[days.length - 1]?.id ?? '' };
    })
    .filter((c) => c.lastDayId);
}

/** Часть, которой принадлежит день, вместе с её неделями и днями. */
export function storyPartOf(
  campaign: StoryCampaign,
  missionId: string
): { part: StoryPart; weeks: StoryWeek[]; missions: StoryMission[] } | null {
  const mission = campaign.missions.find((m) => m.id === missionId);
  const week = campaign.weeks.find((w) => w.id === mission?.week);
  const part = campaign.parts.find((p) => p.id === week?.part);
  if (!part) return null;
  const weeks = campaign.weeks.filter((w) => w.part === part.id);
  return { part, weeks, missions: campaign.missions.filter((m) => weeks.some((w) => w.id === m.week)) };
}

/**
 * Закрывает ли день свою часть — после итога недели идёт экран финиша.
 *
 * Только у частей, у которых финиш написан: последняя часть кончается итогом
 * кампании (см. StoryPart.finish), и второй экран-конец подряд был бы лишним.
 */
export function storyClosesPart(campaign: StoryCampaign, missionId: string): boolean {
  const own = storyPartOf(campaign, missionId);
  return !!own && own.part.finish.length > 0 && own.missions[own.missions.length - 1]?.id === missionId;
}

/** Первый день части, либо null — если такой части нет. */
export function storyFirstMissionOf(campaign: StoryCampaign, partId: string): StoryMission | null {
  const week = campaign.weeks.find((w) => w.part === partId);
  return campaign.missions.find((m) => m.week === week?.id) ?? null;
}

/**
 * Сколько недель после этой остаётся в её части.
 * Обзор недели на брифе понедельника называет конец части, а не кампании:
 * «ещё 7 недель» на первом дне — то самое «испугался и спрыгнул».
 */
export function storyWeeksLeftInPart(
  campaign: StoryCampaign,
  missionId: string
): { left: number; part: StoryPart } | null {
  const own = storyPartOf(campaign, missionId);
  const week = campaign.missions.find((m) => m.id === missionId)?.week;
  if (!own || !week) return null;
  return { left: own.weeks.length - 1 - own.weeks.findIndex((w) => w.id === week), part: own.part };
}

/** Неделя, которой принадлежит день, вместе со своими днями и вопросом. */
export function storyWeekOf(
  campaign: StoryCampaign,
  missionId: string
): { week: StoryWeek; missions: StoryMission[] } | null {
  const mission = campaign.missions.find((m) => m.id === missionId);
  if (!mission) return null;
  const week = campaign.weeks.find((w) => w.id === mission.week);
  if (!week) return null;
  return { week, missions: campaign.missions.filter((m) => m.week === week.id) };
}

/**
 * Закрывает ли день свою неделю — после него идёт итог недели.
 *
 * Считается по кампании, а не по метке «Пт»: неделя — это список её дней,
 * и последний в нём закрывает дело, как бы он ни назывался.
 */
export function storyClosesWeek(campaign: StoryCampaign, missionId: string): boolean {
  const days = storyWeekOf(campaign, missionId)?.missions;
  return !!days && days[days.length - 1]?.id === missionId;
}

/**
 * Закрывает ли день кампанию целиком, а не только свою неделю.
 *
 * День один и тот же (последний в последней неделе), но итогу после него
 * нужны все дни кампании, а не пять дней своей недели, — и это решение
 * нужно раньше, в App и StoryProgress, а не только внутри StoryWeekSummary:
 * иначе граница «неделя vs кампания» жила бы в двух местах и однажды
 * разошлась бы.
 */
export function storyClosesCampaign(campaign: StoryCampaign, missionId: string): boolean {
  return campaign.missions[campaign.missions.length - 1]?.id === missionId;
}

/** Кампания режима истории для локали. */
export function storyCampaign(locale: Locale = 'ru'): StoryCampaign {
  return locale === 'en' ? en : ru;
}
